def case(cid, family, severity, desc_en, desc_ja, *edits, **special):
    c = {"id": cid, "family": family, "severity": severity, "desc_en": desc_en, "desc_ja": desc_ja,
         "edits": list(edits)}
    c.update(special)
    return c

def ed(at, en=None, ja=None):
    e = {"at": at}
    if en is not None:
        e["en"] = en
    if ja is not None:
        e["ja"] = ja
    return e

